contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Run with parameters: amount of ETH to send to Put, and an unlockTime candidate
    function run(uint amount, uint unlockTime) public payable {
        require(address(this).balance >= amount, "insufficient test balance");

        // Read before values observable via public getters
        C.Holder memory before = c.Acc(address(this));
        uint beforeBalance = before.balance;
        uint contractBefore = address(c).balance;

        // Call Put with provided amount and unlockTime, sending Ether
        bool reverted;
        try c.Put{value: amount}(unlockTime) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after values
        C.Holder memory after = c.Acc(address(this));
        uint afterBalance = after.balance;
        uint contractAfter = address(c).balance;

        // General rule: if the call did not revert, then the holder balance increased by exactly amount
        // and the contract balance increased by exactly amount. If it reverted, neither observable balance changed.
        assert(
            (!reverted && afterBalance == beforeBalance + amount && contractAfter == contractBefore + amount)
            || (reverted && afterBalance == beforeBalance && contractAfter == contractBefore)
        );
    }

    // Allow receiving Ether so the test contract can fund calls
    receive() external payable {}
}

contract InvMutTest {
    C c;
