    // Send ETH amount to c.Put with unlockTime; this function is payable so caller can fund the call
    function run(uint amount, uint unlockTime) public payable {
        require(address(this).balance >= amount, "insufficient test balance");

        // Read observable before-values via public getter
        // Note: reading struct via public mapping accessor returns (uint,uint) tuple
        (uint beforeUnlockTime, uint beforeBalance) = c.Acc(address(this));
        uint contractBefore = address(c).balance;

        // Call Put and capture whether it reverted
        bool reverted;
        try c.Put{value: amount}(unlockTime) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after-values
        (uint afterUnlockTime, uint afterBalance) = c.Acc(address(this));
        uint contractAfter = address(c).balance;

        // General invariant: either the call reverted and nothing changed, or it succeeded and both
        // the holder balance and contract balance increased exactly by amount.
        assert(
            (reverted && afterBalance == beforeBalance && contractAfter == contractBefore && afterUnlockTime == beforeUnlockTime)
            ||
            (!reverted && afterBalance == beforeBalance + amount && contractAfter == contractBefore + amount)
        );
    }

    // Allow receiving Ether so the test contract can fund calls
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Attempt to Collect _am from c for this contract's address; send no ETH with this call.
    // We require nothing about _am (can be zero). The test contract must have sufficient balance
    // in c beforehand for the successful branch, so we set that up by calling Put first.
    function run(uint seedInitial, uint putAmount, uint collectAmount, uint putUnlock) public payable {
        // fund this test contract so it can call c.Put{value: putAmount}
        require(address(this).balance >= putAmount, "insufficient test balance");

        // Ensure a predictable starting state: deposit putAmount into c under this contract's holder
        // via Put. We allow Put to possibly revert; capture whether it reverted.
        bool putReverted;
        try c.Put{value: putAmount}(putUnlock) {
            putReverted = false;
        } catch {
            putReverted = true;
        }

        // Observe before-values for this holder and contract balance
        (uint beforeUnlock, uint beforeBal) = c.Acc(address(this));
        uint contractBefore = address(c).balance;

        // Now try to Collect collectAmount. Capture whether it reverted.
        bool collectReverted;
        try c.Collect{value:0}(collectAmount) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        // Observe after-values
        (uint afterUnlock, uint afterBal) = c.Acc(address(this));
        uint contractAfter = address(c).balance;

        // General rule:
        // If Collect succeeded then the holder's balance decreased by exactly collectAmount
        // and the contract balance decreased by exactly collectAmount. If Collect reverted then
        // neither the holder's balance nor the contract balance increased as a result of Collect
        // (they must be equal to what they were immediately after Put call).
        // Note: Put may have reverted; we reason from the observed before/after around Collect.
        assert(
            (collectReverted && afterBal == beforeBal && contractAfter == contractBefore)
            ||
            (!collectReverted && afterBal + collectAmount == beforeBal && contractAfter + collectAmount == contractBefore)
        );
    }

    // Allow receiving Ether so the test contract can fund Put
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will optionally deposit some ETH first to ensure there is some state to observe.
    // Inputs:
    //  depositAmount - amount to send to c.Put (can be zero)
    //  depositUnlock - unlock time passed to Put
    //  collectAmount - amount to attempt to Collect
    function run(uint depositAmount, uint depositUnlock, uint collectAmount) public payable {
        // Ensure this test contract can fund the Put call if needed
        require(address(this).balance >= depositAmount, "insufficient balance to fund Put");

        // Perform a Put to set up a holder entry for this contract (may revert)
        bool putReverted;
        try c.Put{value: depositAmount}(depositUnlock) {
            putReverted = false;
        } catch {
            putReverted = true;
        }

        // Observe balances before Collect
        (uint beforeUnlock, uint beforeBal) = c.Acc(address(this));
        uint contractBefore = address(c).balance;

        // Attempt Collect; capture whether it reverted
        bool collectReverted;
        try c.Collect{value:0}(collectAmount) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        // Observe after-values
        (uint afterUnlock, uint afterBal) = c.Acc(address(this));
        uint contractAfter = address(c).balance;

        // General rule: Collect must NOT increase the holder's recorded balance nor the contract's balance.
        // (They may stay the same or decrease.) This must hold regardless of whether Put or Collect reverted.
        assert(afterBal <= beforeBal && contractAfter <= contractBefore);
    }

    // Allow receiving Ether so the test contract can fund Put
    receive() external payable {}
}

