contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will deposit some value and then attempt to Collect some amount.
    function run(uint unlockOffset, uint depositAmount, uint collectAmount) public payable {
        require(address(this).balance >= depositAmount, "insufficient balance for deposit");

        // 1) Put funds into c from this contract (msg.sender for c will be this contract)
        c.Put{value: depositAmount}(block.timestamp + unlockOffset);

        // Read recorded balance before collect via public getter Acc(address)
        (uint beforeUnlock, uint beforeBalance) = c.Acc(address(this));
        // record contract balance of c before
        uint cBalanceBefore = address(c).balance;

        // Try to Collect collectAmount. It may revert; capture that.
        bool reverted;
        try c.Collect{value: 0}(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read recorded balance after
        (uint afterUnlock, uint afterBalance) = c.Acc(address(this));
        uint cBalanceAfter = address(c).balance;

        // General rule: if Collect succeeded (not reverted) then:
        // - the recorded balance decreased by exactly collectAmount
        // - and the contract's Ether balance decreased by at least collectAmount
        // If Collect reverted, no guarantees about balances, so allow any values.
        assert(reverted || (beforeBalance >= collectAmount && beforeBalance - afterBalance == collectAmount && cBalanceBefore >= cBalanceAfter && cBalanceBefore - cBalanceAfter >= collectAmount));
    }

    receive() external payable { }
}

