        // must have enough Ether to seed the deposit
        require(address(this).balance >= depositAmount);

        // First, ensure this test contract has a recorded balance by calling Put with depositAmount
        // We capture whether Put reverted
        bool putReverted = false;
        try c.Put{value: depositAmount}(depositUnlock) {
            putReverted = false;
        } catch {
            putReverted = true;
        }

        // Read observable state for this test contract's holder entry and contract balance
        // c.Acc(address(this)) is a public mapping returning (unlockTime, balance) tuple
        (uint accUnlockAfter, uint accBalanceAfter) = c.Acc(address(this));
        uint contractBalanceAfterPut = address(c).balance;

        // Try to call Collect with collectAmount and record whether it reverted
        bool collectReverted = false;
        try c.Collect{value: 0}(collectAmount) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        // Read state after Collect
        (uint accUnlockFinal, uint accBalanceFinal) = c.Acc(address(this));
        uint contractBalanceFinal = address(c).balance;

        // General invariant to assert:
        // If Collect did not revert, then (1) the contract's ether balance did not increase due to Collect,
        // and (2) the amount withdrawn (difference in accBalanceAfter - accBalanceFinal) is at most the recorded balance before Collect
        // If Collect reverted, no guarantees about balances changing (they should not change), so allow either.
        // We express: collectReverted || (contractBalanceFinal <= contractBalanceAfterPut && accBalanceAfter >= accBalanceFinal && accBalanceAfter - accBalanceFinal <= collectAmount)

        assert(collectReverted || (contractBalanceFinal <= contractBalanceAfterPut && accBalanceAfter >= accBalanceFinal && accBalanceAfter - accBalanceFinal <= collectAmount));
    }

    // Allow receiving ETH if contract sends any
    receive() external payable {}
}

