    // params: deposit unlock time, deposit amount, collect amount
    function run(uint depositUnlock, uint depositAmount, uint collectAmount) public payable {
        // ensure this test contract has enough ether to perform the deposit
        require(address(this).balance >= depositAmount);

        // Perform a Put to set up Acc for this contract (may revert)
        bool putReverted = false;
        try c.Put{value: depositAmount}(depositUnlock) {
            putReverted = false;
        } catch {
            putReverted = true;
        }

        // Observe before state
        (uint accUnlockBefore, uint accBalBefore) = c.Acc(address(this));
        uint minSum = c.MinSum();
        uint contractBalBefore = address(c).balance;

        // Try Collect and record whether it reverted
        bool collectReverted = false;
        try c.Collect{value: 0}(collectAmount) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        // Observe after state
        (uint accUnlockAfter, uint accBalAfter) = c.Acc(address(this));
        uint contractBalAfter = address(c).balance;

        // General rule:
        // If Collect succeeded then:
        // 1) the recorded balance decreased by exactly collectAmount, and
        // 2) Collect's preconditions held: accBalBefore >= minSum, accBalBefore >= collectAmount, and block.timestamp > accUnlockBefore.
        // We can't read block.timestamp directly, but accUnlockBefore < block.timestamp is equivalent to accUnlockBefore < accUnlockAfter || accUnlockBefore < block.timestamp observed by comparing to current block time isn't possible; however the contract uses block.timestamp at call time, so a necessary observable condition is accUnlockBefore < block.timestamp at the time of the call — we approximate by requiring accUnlockBefore < block.timestamp via comparing to accUnlockAfter when unchanged by Put/Collect; instead we check the three numeric preconditions that are public: balances and MinSum.

        assert(collectReverted || (accBalAfter + collectAmount == accBalBefore && accBalBefore >= minSum && accBalBefore >= collectAmount));
    }

    // accept incoming ether when Collect sends funds
    receive() external payable {}
}

