    //  - fundAmt: amount we first deposit into c so there is something to collect
    //  - collectAmt: amount we then attempt to collect
    //  - fundUnlock: unlock time used when funding
    function run(uint fundAmt, uint collectAmt, uint fundUnlock) public payable {
        // ensure this contract has enough ETH to fund
        require(address(this).balance >= fundAmt, "insufficient funds for fundAmt");

        // Make an initial Put to create balance for this test contract
        // read balances before
        (uint beforeUnlock, uint beforeBalance) = c.Acc(address(this));
        uint cBalBefore = address(c).balance;

        bool putReverted;
        try c.Put{value: fundAmt}(fundUnlock) {
            putReverted = false;
        } catch {
            putReverted = true;
        }

        // After Put (or attempted Put), read observed state
        (uint midUnlock, uint midBalance) = c.Acc(address(this));
        uint cBalMid = address(c).balance;

        // Now attempt Collect of collectAmt (may revert)
        bool collectReverted;
        try c.Collect{value: 0}(collectAmt) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        // Read after values
        (uint afterUnlock, uint afterBalance) = c.Acc(address(this));
        uint cBalAfter = address(c).balance;

