        // (i.e. afterBalance == midBalance - collectAmt) OR the contract's external ether decreased by at least collectAmt
        // (i.e. cBalAfter + collectAmt <= cBalMid), ensuring some observable outflow.
        // We must avoid underflow in the assert, so express stored-decrease equality only when midBalance >= collectAmt.
        bool storedDecreasedExactly = (midBalance >= collectAmt) ? (afterBalance == midBalance - collectAmt) : false;
        bool extBalanceDecreasedAtLeast = (cBalAfter + collectAmt <= cBalMid);

        assert(collectReverted || storedDecreasedExactly || extBalanceDecreasedAtLeast);
