        uint beforeContractBal = address(c).balance;

        // Perform the deposit either via Put or via fallback
        if (useFallback) {
            // call fallback by sending to c with no data
            (bool s,) = address(c).call{value: amount}("");
            // ensure call succeeded is captured in a local for the assertion
            // but do not revert here; we will assert about behavior including success flag
            // store success in a local by using a trivial assignment
            // (we cannot reference s in the final assert if not declared earlier) -- keep s
            // continue
        } else {
            c.Put{value: amount}(unlockTime);
        }

        // Read after values
        (uint afterUnlock, uint afterBalance) = c.Acc(address(this));
        uint afterContractBal = address(c).balance;

        // General rule: if the call sent amount wei and did not revert, then
        // the recorded balance increases by amount and contract balance increases by amount.
        // We express this by requiring that afterBalance >= beforeBalance and afterContractBal >= beforeContractBal
        // and that the differences are equal to amount when the call succeeded.

        // Detect success: if contract balance increased by amount then the call succeeded in transferring Ether in.
        bool successObserved = (afterContractBal == beforeContractBal + amount);

        assert(
            // never decreases stored balance
            afterBalance >= beforeBalance
            &&
            // observed successful Ether transfer implies stored balance increased by exactly amount
            ( (!successObserved) || (afterBalance == beforeBalance + amount && afterContractBal == beforeContractBal + amount) )
        );
    }

